const norm = (s: any) =>
  String(s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .trim()

const clave = (r: any) =>
  [norm(r.clienteNombre), r.fechaEnvioAseguradora ?? '', norm(r.liquidacion), r.valor ?? ''].join('|')

@Injectable()
export class CargaReclamosService {
  private readonly logger = new Logger(CargaReclamosService.name)

  constructor(private readonly prisma: PrismaService) {}

  async cargar(organizationId: string, simular: boolean) {
    // Resolver ejecutivas por nombre. Las que ya no trabajan aquí no van a
    // aparecer, y sus reclamos quedan con el nombre en texto pero sin usuario.
    const usuarios = await this.prisma.user.findMany({
      where: { organizationId },
      select: { id: true, name: true },
    })
    const porApellido = new Map<string, string>()
    for (const u of usuarios) {
      for (const parte of norm(u.name).split(/\s+/)) {
        if (parte.length > 2 && !porApellido.has(parte)) porApellido.set(parte, u.id)
      }
    }
    const resolver = (nombre?: string | null): string | null => {
      if (!nombre) return null
      for (const parte of norm(nombre).split(/\s+/)) {
        const id = porApellido.get(parte)
        if (id) return id
      }
      return null
    }

    // Lo ya cargado, para no duplicar si se corre dos veces.
    const existentes = await this.prisma.reclamo.findMany({
      where: { organizationId },
      select: {
        clienteNombre: true,
        fechaEnvioAseguradora: true,
        liquidacion: true,
        valor: true,
      },
    })
    const yaEstan = new Set(
      existentes.map((r) =>
        clave({
          clienteNombre: r.clienteNombre,
          fechaEnvioAseguradora: r.fechaEnvioAseguradora
            ? r.fechaEnvioAseguradora.toISOString().slice(0, 10)
            : '',
          liquidacion: r.liquidacion,
          valor: r.valor ? Number(r.valor) : '',
        }),
      ),
    )

    const nuevos = RECLAMOS.filter((r) => !yaEstan.has(clave(r)))
    const sinUsuario = new Set<string>()
    const porEjecutiva: Record<string, number> = {}

    for (const r of RECLAMOS) {
      const nombre = r.ejecutivoNombre ?? '(sin ejecutiva)'
      porEjecutiva[nombre] = (porEjecutiva[nombre] ?? 0) + 1
      if (r.ejecutivoNombre && !resolver(r.ejecutivoNombre)) sinUsuario.add(r.ejecutivoNombre)
    }

    if (simular) {
      return {
        ok: true,
        modo: 'SIMULACION — no se escribio nada',
        enElArchivo: RECLAMOS.length,
        seCargarian: nuevos.length,
        yaEstabanCargados: RECLAMOS.length - nuevos.length,
        porEjecutiva,
        ejecutivasSinUsuarioEnElCrm: [...sinUsuario],
        nota: 'Los reclamos de quienes ya no trabajan aqui se cargan igual, con el nombre en texto y sin usuario asignado.',
        siguientePaso: 'Repetir agregando &confirm=si-cargar para ejecutar',
      }
    }

    // Insertar por lotes: 1.800 inserciones de una sola vez puede tumbar la conexión.
    const LOTE = 200
    let creados = 0
    for (let i = 0; i < nuevos.length; i += LOTE) {
      const bloque = nuevos.slice(i, i + LOTE).map((r) => ({
        organizationId,
        clienteNombre: r.clienteNombre,
        pacienteNombre: r.pacienteNombre ?? null,
        aseguradora: r.aseguradora ?? null,
        contrato: r.contrato ?? null,
        diagnostico: r.diagnostico ?? null,
        fechaRecepcion: r.fechaRecepcion ? new Date(r.fechaRecepcion) : null,
        fechaEnvioAseguradora: r.fechaEnvioAseguradora ? new Date(r.fechaEnvioAseguradora) : null,
        liquidacion: r.liquidacion ?? null,
        fechaLiquidacion: r.fechaLiquidacion ? new Date(r.fechaLiquidacion) : null,
        fechaEnvioCliente: r.fechaEnvioCliente ? new Date(r.fechaEnvioCliente) : null,
        valor: r.valor ?? null,
        estado: r.estado ?? 'EN_TRAMITE',
        medioComunicacion: r.medioComunicacion ?? null,
        observaciones: r.observaciones ?? null,
        detalle: r.detalle ?? null,
        ejecutivoId: resolver(r.ejecutivoNombre),
        ejecutivoNombre: r.ejecutivoNombre ?? null,
      }))
      const res = await this.prisma.reclamo.createMany({ data: bloque as any })
      creados += res.count
      this.logger.log(`Reclamos cargados: ${creados}/${nuevos.length}`)
    }

    const total = await this.prisma.reclamo.count({ where: { organizationId } })
    return {
      ok: true,
      modo: 'EJECUTADO',
      creados,
      totalEnBase: total,
      porEjecutiva,
      ejecutivasSinUsuarioEnElCrm: [...sinUsuario],
    }
  }
}
